'use strict';
const $=(q,root=document)=>root.querySelector(q), $$=(q,root=document)=>[...root.querySelectorAll(q)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const copy=v=>JSON.parse(JSON.stringify(v));
const assetUrl=v=>/^https:\/\//i.test(v||'')?v:'../'+v;
const S={csrf:'',user:null,c:null,view:'dashboard',dirty:false,media:[],page:null,slot:null,selected:null,undo:[],redo:[],setupKey:new URLSearchParams(location.hash.slice(1)).get('setup')||'',query:'',archived:false};
const labels={dashboard:'Обзор',pages:'Страницы',products:'Товары',categories:'Группы товаров',brands:'Бренды',offers:'Акции',media:'Медиатека',common:'Общие блоки',navigation:'Меню сайта',settings:'Компания и настройки',inquiries:'Обращения',history:'Версии и резервные копии',users:'Пользователи',audit:'Журнал действий',account:'Моя учётная запись'};
const entityNames={products:'товар',categories:'группу',brands:'бренд',offers:'акцию'};
const typeNames={bulldozer:'Бульдозеры',loader:'Погрузчики',dumptruck:'Карьерные самосвалы',grader:'Грейдеры'};
const date=v=>v?new Date(v).toLocaleString('ru-RU',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}):'—';
const prettyAction=v=>({page_saved:'Страница сохранена',common_saved:'Общий блок сохранён',settings_saved:'Настройки сохранены',navigation_saved:'Меню сохранено',products_saved:'Товар сохранён',categories_saved:'Группа сохранена',brands_saved:'Бренд сохранён',offers_saved:'Акция сохранена',products_imported:'Каталог импортирован',media_uploaded:'Файл загружен',media_saved:'Медиатека изменена',restored:'Версия восстановлена',backup_imported:'Копия импортирована',publish:'Сайт опубликован',setup:'Первый вход настроен',login:'Вход в панель',logout:'Выход из панели',login_failed:'Неудачный вход',password_changed:'Пароль изменён',user_saved:'Пользователь сохранён',inquiry_received:'Новое обращение',inquiry_status:'Статус обращения изменён'}[v]||v.replace('_archived',' — архив'));
let noticeTimer;
function toast(text,error=false){const n=$('#notice');n.textContent=text;n.className='show'+(error?' error':'');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>n.className='',5500);}
async function api(action,data){
 const opt={credentials:'same-origin',headers:{}};if(data!==undefined){opt.method='POST';opt.headers['X-CSRF-Token']=S.csrf;if(data instanceof FormData) opt.body=data;else{opt.headers['Content-Type']='application/json';opt.body=JSON.stringify(data);}}
 const r=await fetch('api.php?action='+encodeURIComponent(action),opt);let value;try{value=await r.json();}catch{throw Error('Сервер вернул некорректный ответ. Проверьте подключение.');}
 if(!r.ok||value.success===false){if(r.status===401 && S.user){S.user=null;renderAuth(true);}throw Error(value.error||'Не удалось выполнить действие.');}
 if(value.csrf) S.csrf=value.csrf;if(value.content) S.c=value.content;if(value.user) S.user=value.user;return value;
}
function btn(label,action,extra='',style=''){return `<button type="button" class="btn ${style}" data-action="${action}" ${extra}>${label}</button>`;}
function field(name,label,value='',type='text',help='',extra=''){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}>${help?`<small>${help}</small>`:''}</div>`;}
function area(name,label,value='',help='',extra=''){return `<div class="field ${extra}"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}">${esc(value)}</textarea>${help?`<small>${help}</small>`:''}</div>`;}
function check(name,label,value=false,help=''){return `<label class="check"><input type="checkbox" name="${name}" ${value?'checked':''}><span>${label}${help?`<small class="muted" style="display:block">${help}</small>`:''}</span></label>`;}
function select(name,label,value,items,help=''){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${items.map(v=>`<option value="${esc(v[0])}" ${String(v[0])===String(value)?'selected':''}>${esc(v[1])}</option>`).join('')}</select>${help?`<small>${help}</small>`:''}</div>`;}
function imageField(name,label,value=''){return `<div class="field"><label for="f-${name}">${label}</label><div class="file-field"><input id="f-${name}" name="${name}" value="${esc(value)}" placeholder="assets/… или https://…">${btn('Выбрать','pick-field',`data-field="${name}"`,'small')}</div></div>`;}
function formValues(form){const v=Object.fromEntries(new FormData(form));$$('input[type=checkbox]',form).forEach(e=>{if(e.name!=='types')v[e.name]=e.checked;});if($('input[name=types]',form))v.types=$$('input[name=types]:checked',form).map(e=>e.value);return v;}
function modal(title,body,footer=''){const d=$('#modal');d.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="modal-close" type="button" data-action="close-modal" aria-label="Закрыть окно">×</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!d.open)d.showModal();return d;}
function confirmBox(title,text,label='Продолжить',danger=false){return new Promise(resolve=>{modal(title,`<p class="confirm-text">${text}</p>`,`${btn('Отмена','close-modal')}${btn(label,'modal-confirm','',danger?'danger':'primary')}`);const d=$('#modal');$('#modal [data-action=modal-confirm]').onclick=()=>{d.close();resolve(true);};d.addEventListener('close',()=>resolve(false),{once:true});});}
function changed(){S.dirty=true;const n=$('#form-status');if(n)n.innerHTML='<span class="dirty-dot"></span>Есть несохранённые изменения';}
function saved(){S.dirty=false;const n=$('#form-status');if(n)n.textContent='Черновик сохранён · '+date(S.c.updatedAt);updateTop();}
function updateTop(){const n=$('#publish-state');if(n){const draft=S.c.revision!==S.c.publishedRevision;n.className='pill '+(draft?'yellow':'green');n.textContent=draft?'Есть черновик':'Опубликовано';}}
function pageHead(title,sub,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`;}
async function go(view){if(S.dirty && !await confirmBox('Изменения не сохранены','Уйти из открытой формы? Сохранённые ранее черновики останутся в панели.','Уйти без сохранения',true))return;S.dirty=false;S.view=view;S.query='';S.archived=false;history.replaceState(null,'',location.pathname+'#'+view);renderShell();await renderView();}
function renderAuth(installed,ready=true){
 const setup=!installed&&S.setupKey&&ready;
 $('#app').innerHTML=`<div class="auth-wrap"><section class="auth-brand"><img src="../assets/specparts49-emblem.png" alt="Спецпартс49"><h1>Ваш сайт.<br><span>Под вашим<br>управлением.</span></h1><p>Страницы, товары, наличие и обращения — в одной панели. Изменения можно сохранить в черновике и опубликовать, когда всё готово.</p></section><main class="auth-form"><h2>${setup?'Первый вход':installed?'Вход в панель':'Панель подготавливается'}</h2><p class="sub">${setup?'Создайте личную учётную запись администратора. Ссылка первоначальной настройки действует только один раз.':installed?'Используйте email и пароль своей учётной записи.':'Первоначальная настройка доступна владельцу по защищённой ссылке.'}</p>${installed||setup?`<form id="auth-form" data-mode="${setup?'setup':'login'}">${setup?field('name','Ваше имя','','text','', 'autocomplete="name" required'):''}${field('email','Email','','email','', 'autocomplete="username" required')}${field('password','Пароль','','password',setup?'Не менее 12 символов. Используйте уникальный пароль.':'',`autocomplete="${setup?'new-password':'current-password'}" ${setup?'minlength="12"':''} maxlength="200" required`)}${setup?field('passwordRepeat','Повторите пароль','','password','','autocomplete="new-password" minlength="12" required'):''}<p id="auth-error" class="error" role="alert"></p><button class="btn primary wide" type="submit">${setup?'Создать администратора':'Войти'}</button></form>`:`<div class="warning">${ready?'Откройте ссылку настройки, полученную от разработчика.':'Доступ к настройке ещё не подготовлен.'}</div>`}<div class="auth-footer"><a href="../index.html">← Вернуться на сайт</a></div></main></div>`;
 $('#auth-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,b=$('button[type=submit]',f);b.disabled=true;$('#auth-error').textContent='';try{await api(f.dataset.mode,{...formValues(f),key:S.setupKey});S.setupKey='';history.replaceState(null,'',location.pathname);await load();}catch(error){$('#auth-error').textContent=error.message;}finally{b.disabled=false;}});
}
function renderShell(){
 const links=(items)=>items.map(([key,icon])=>`<a href="#${key}" data-nav="${key}" class="${S.view===key?'active':''}"><span class="nav-icon" aria-hidden="true">${icon}</span>${labels[key]}</a>`).join('');
 $('#app').innerHTML=`<div class="layout"><aside class="sidebar" id="sidebar"><a class="side-brand" href="#dashboard" data-nav="dashboard"><img src="../assets/specparts49-emblem.png" alt=""><span>СПЕЦПАРТС49<small>ПАНЕЛЬ УПРАВЛЕНИЯ</small></span></a><nav class="side-nav">${links([['dashboard','◫']])}<div class="nav-label">Содержание</div>${links([['pages','▤'],['products','▦'],['categories','⊞'],['brands','◇'],['offers','%'],['media','▧']])}<div class="nav-label">Сайт и компания</div>${links([['inquiries','✉'],['common','▥'],['navigation','☰'],...(S.user.role==='owner'?[['settings','⚙']]:[]),['history','↶']])}${S.user.role==='owner'?`<div class="nav-label">Управление</div>${links([['users','♙'],['audit','≡']])}`:''}</nav><div class="side-user"><strong>${esc(S.user.name||S.user.email)}</strong><small>${S.user.role==='owner'?'Администратор':'Редактор'}</small><div class="side-bottom"><button data-nav="account">Мой аккаунт</button><button data-action="logout">Выйти</button></div></div></aside><div class="workspace"><header class="top"><div class="top-left"><button class="mobile-menu" data-action="toggle-nav" aria-label="Открыть меню панели">☰</button><div><strong>${esc(S.c.settings.companyName)}</strong><small>Публикация: ${date(S.c.publishedAt)}</small></div></div><div class="top-right"><span id="publish-state" class="pill"></span><a class="btn quiet" href="../index.html" target="_blank" rel="noopener">Открыть сайт ↗</a>${btn('Опубликовать','publish','','primary')}</div></header><main class="main" id="workspace-main"></main></div></div>`;updateTop();
}
async function load(){const r=await api('data');S.c=r.content;S.user=r.user;S.view='dashboard';S.dirty=false;renderShell();await renderView();}
function renderDashboard(){
 const c=S.c;const visible=k=>c[k].filter(v=>!v.archived);const examples=visible('products').filter(v=>v.example).length;
 $('#workspace-main').innerHTML=pageHead('Управление сайтом','Редактируйте материалы, сохраняйте черновики и публикуйте готовые изменения.')+`<section class="panel hero-panel"><div><div class="overline">Спецпартс49 / рабочее пространство</div><h2>Актуальный сайт —<br>уверенность ваших клиентов.</h2><p>Начните с каталога, обновите наличие или измените содержание страницы. До публикации посетители будут видеть действующую версию.</p></div><div class="actions">${btn('Редактировать страницы ↗','nav-pages','','primary')}${btn('Добавить товар +','entity-new','data-collection="products"','quiet')}</div></section><div class="stats">${[['Страницы',Object.values(c.pages).filter(p=>!p.archived).length,'Материалы и SEO'],['Товары',visible('products').length,examples?`${examples} примеров — замените своими`:'Ассортимент компании'],['Бренды',visible('brands').length,'Логотипы и производители'],['Акции',visible('offers').length,'Специальные предложения']].map(([a,b,d])=>`<div class="stat"><small>${a}</small><strong>${b}</strong><span>${d}</span></div>`).join('')}</div><div class="two-col"><section class="panel"><h2>Быстрые действия</h2>${[['products','Ассортимент и наличие','Товары, артикулы, цены и остатки'],['settings','Контакты компании','Телефон, email, реквизиты и склад'],['media','Изображения и документы','Фото, логотипы и PDF'],['navigation','Навигация сайта','Порядок и названия пунктов меню']].filter(([k])=>k!=='settings'||S.user.role==='owner').map(([k,t,d])=>`<a class="quick-item" href="#${k}" data-nav="${k}"><div><strong>${t}</strong><small>${d}</small></div><span>↗</span></a>`).join('')}</section><section class="panel"><h2>Состояние сайта</h2><ul class="info-list"><li><span>Версия черновика</span><strong>№ ${c.revision}</strong></li><li><span>Опубликованная версия</span><strong>№ ${c.publishedRevision}</strong></li><li><span>Поисковая индексация</span><strong>${c.settings.indexing?'Открыта':'Закрыта'}</strong></li><li><span>Приём обращений</span><strong>${c.settings.inquiriesEnabled?'Подключён':'Ожидает настройки'}</strong></li><li><span>Почтовые уведомления</span><strong>${c.settings.mailNotifications?'Включены':'Выключены'}</strong></li></ul>${!c.settings.inquiriesEnabled?'<p class="muted">Приём обращений можно включить в настройках после заполнения контактов компании.</p>':''}</section></div>`;
}
function renderPages(){const rows=Object.values(S.c.pages).filter(p=>!S.query||(p.file+' '+p.title).toLowerCase().includes(S.query.toLowerCase()));$('#workspace-main').innerHTML=pageHead('Страницы','Тексты, изображения, разделы и поисковые настройки. Шапка и подвал редактируются в общих блоках.',btn('Создать страницу +','page-new','','primary'))+`<div class="toolbar"><input class="search" data-search="pages" placeholder="Найти страницу" aria-label="Поиск страниц" value="${esc(S.query)}"><span class="muted">${rows.length} страниц</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Страница</th><th>Адрес</th><th>Индексация</th><th>Статус</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td><strong>${esc(p.title)}</strong></td><td>${esc(p.file)}</td><td>${p.noindex?'Закрыта':'По настройке сайта'}</td><td><span class="pill ${p.archived?'':'green'}">${p.archived?'Архив':'Активна'}</span></td><td>${btn('Редактировать','page-edit',`data-id="${p.file}"`,'small')}</td></tr>`).join('')}</tbody></table></div>`;}
function renderEntities(key){const rows=S.c[key].filter(v=>!!v.archived===S.archived).filter(v=>(v.name+' '+(v.article||'')+' '+(v.brand||'')+' '+v.id).toLowerCase().includes(S.query.toLowerCase()));
 const actions=(key==='products'?`${btn('Импорт CSV','import-products')}${btn('Экспорт CSV','export-products')}`:'')+btn('Добавить '+entityNames[key]+' +','entity-new',`data-collection="${key}"`,'primary');
 $('#workspace-main').innerHTML=pageHead(labels[key],key==='products'?'Карточки, применяемость, цены и складские остатки. Примеры помечены отдельно от реального ассортимента.':key==='categories'?'Группы товаров в каталоге и на главной странице.':key==='brands'?'Бренды и логотипы на главной и странице производителей.':'Предложения и распродажа складских позиций. Акции с прошедшей датой автоматически скрываются.',actions)+`<div class="toolbar"><input class="search" data-search="${key}" aria-label="Поиск в разделе" placeholder="Поиск по названию${key==='products'?', артикулу или бренду':''}" value="${esc(S.query)}"><div class="actions">${btn(S.archived?'Показать активные':'Архив','entity-archive-view',`data-collection="${key}"`,'small')}<span class="muted">${rows.length} записей</span></div></div>${rows.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>${key==='products'?'Товар':'Название'}</th>${key==='products'?'<th>Артикул / бренд</th><th>Цена / остаток</th>':key==='categories'?'<th>Товаров</th>':'<th>Порядок</th>'}<th>Статус</th><th></th></tr></thead><tbody>${rows.map(v=>`<tr><td><div class="inline-name">${v.image||v.logo?`<img class="thumb" src="${esc(assetUrl(v.image||v.logo))}" alt="">`:''}<div><strong>${esc(v.name)}</strong><small>${esc(v.id)}${v.example?' · пример позиции':''}</small></div></div></td>${key==='products'?`<td>${esc(v.article||'Не указан')}<small>${esc(v.brand||'Бренд не выбран')}</small></td><td>${v.price!=null?Number(v.price).toLocaleString('ru-RU')+' ₽':'По запросу'}<small>${v.quantity!=null?v.quantity+' шт.':({unknown:'Наличие уточняется',in_stock:'В наличии',on_order:'Под заказ',out_of_stock:'Нет в наличии'}[v.stock]||'Наличие уточняется')}</small></td>`:key==='categories'?`<td>${S.c.products.filter(p=>p.cat===v.id&&!p.archived).length}</td>`:`<td>${v.order||0}</td>`}<td><span class="pill ${v.published?'green':''}">${v.published?'На сайте':'Черновик'}</span></td><td><div class="actions">${btn('Изменить','entity-edit',`data-collection="${key}" data-id="${v.id}"`,'small')}${btn(v.archived?'Восстановить':'В архив','entity-archive',`data-collection="${key}" data-id="${v.id}"`,'small')}</div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><h2>Пока нет записей</h2><p>Добавьте первую запись в этом разделе.</p></div>'}`;
}
function newEntity(key){return {id:'',name:'',published:key==='categories',order:S.c[key].length,description:'',...(key==='products'?{article:'',brand:'',cat:S.c.categories.find(c=>!c.archived)?.id||'engine',types:Object.keys(typeNames),stock:'unknown',quantity:null,price:null,desc:'',image:'assets/gear.svg',asset:'gear',example:false}:key==='brands'?{logo:'',dark:false}:key==='categories'?{image:'assets/gear.svg'}:{title:'',article:'',manufacturer:'',image:'',price:'',oldPrice:'',until:''})};}
function editEntity(key,id){S.entity=copy(id?S.c[key].find(v=>v.id===id):newEntity(key));S.collection=key;S.entityIsNew=!id;S.view='edit-'+key;S.dirty=false;renderEntityForm();}
function renderEntityForm(){const key=S.collection,v=S.entity;$('#workspace-main').innerHTML=pageHead((S.entityIsNew?'Добавить ':'Редактировать ')+entityNames[key],labels[key],btn('← К списку','back-entities',`data-collection="${key}"`))+`<form id="entity-form" class="form-block"><section class="panel"><div class="grid-form">${field('name','Название',v.name,'text','','required maxlength="250"')}${field('id','Идентификатор',v.id,'text','Латинские буквы, цифры и дефис.',`${S.entityIsNew?'':'readonly'} required pattern="[a-z0-9][a-z0-9-]{0,79}"`)}${key==='products'?`${field('article','Артикул',v.article)}${field('brand','Бренд',v.brand,'text','','list="brand-names"')}<datalist id="brand-names">${S.c.brands.filter(b=>!b.archived).map(b=>`<option value="${esc(b.name)}">`).join('')}</datalist>${select('cat','Группа товаров',v.cat,S.c.categories.filter(c=>!c.archived).map(c=>[c.id,c.name]))}${select('stock','Наличие',v.stock,[['unknown','Уточняется'],['in_stock','В наличии'],['on_order','Под заказ'],['out_of_stock','Нет в наличии']])}${field('quantity','Остаток, шт.',v.quantity??'','number','Пустое поле — точное количество не показывается.','min="0" step="1"')}${field('price','Цена, ₽',v.price??'','number','Пустое поле — цена по запросу.','min="0" step="0.01"')}${imageField('image','Изображение',v.image||'assets/'+v.asset+'.svg')}<div class="field"><label>Типы техники</label><div class="types">${Object.entries(typeNames).map(([id,label])=>`<label class="check"><input type="checkbox" name="types" value="${id}" ${v.types?.includes(id)?'checked':''}><span>${label}</span></label>`).join('')}</div></div>${area('desc','Описание',v.desc,'Назначение, применяемость и данные для подбора.','full')}${area('specs','Характеристики',v.specs||'','Одна характеристика на строку: «Размер: 100 мм».','full')}${field('seoTitle','SEO-заголовок товара',v.seoTitle||'')}${area('seoDescription','Описание товара для поиска',v.seoDescription||'','Пустое поле — используется основное описание.','full')}<div class="full">${check('example','Это демонстрационный пример, а не подтверждённая складская позиция',v.example)}</div>`:key==='brands'?`${imageField('logo','Логотип',v.logo)}${field('order','Порядок отображения',v.order,'number','','min="0" step="1"')}${area('description','Описание бренда',v.description,'','full')}<div class="full">${check('dark','Тёмная подложка под белым логотипом',v.dark)}</div>`:key==='categories'?`${imageField('image','Изображение группы',v.image)}${field('order','Порядок отображения',v.order,'number','','min="0" step="1"')}${area('description','Краткое описание',v.description,'Показывается на главной под названием группы.','full')}`:`${field('article','Артикул',v.article)}${field('manufacturer','Производитель',v.manufacturer)}${field('price','Акционная цена',v.price,'text','Например: 15 000 ₽ или «По запросу».')}${field('oldPrice','Прежняя цена',v.oldPrice)}${imageField('image','Изображение',v.image)}${field('until','Показывать до',v.until,'date','Пустое поле — без ограничения даты.')}${field('order','Порядок отображения',v.order,'number','','min="0" step="1"')}${area('description','Описание',v.description||'','','full')}`}</div>${check('published','Показывать на сайте после публикации',v.published)}<p class="error" id="entity-error"></p></section><div class="settings-sticky"><span class="last-save" id="form-status">Изменения сохраняются в черновик</span><button class="btn primary" type="submit">Сохранить черновик</button></div></form>`;
 const form=$('#entity-form');form.addEventListener('input',changed);if(S.entityIsNew){$('input[name=name]',form).addEventListener('input',e=>{const id=$('input[name=id]',form);if(!id.dataset.manual)id.value=slug(e.target.value);});$('input[name=id]',form).addEventListener('input',e=>e.target.dataset.manual='1');}
 form.addEventListener('submit',async e=>{e.preventDefault();try{const item={...v,...formValues(form)};if(key==='offers')item.title=item.name;await api('entitySave',{revision:S.c.revision,collection:key,item});saved();toast('Черновик сохранён');await go(key);}catch(error){$('#entity-error').textContent=error.message;}});
}
function slug(text){const from='абвгдеёжзийклмнопрстуфхцчшщъыьэюя',to=['a','b','v','g','d','e','e','zh','z','i','i','k','l','m','n','o','p','r','s','t','u','f','h','ts','ch','sh','sch','','y','','e','yu','ya'];return text.toLowerCase().split('').map(c=>from.includes(c)?to[from.indexOf(c)]:c).join('').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,70)||'';}
async function renderMedia(picker=false,onPick=null){const result=await api('media');S.media=result.media;const body=`<div class="toolbar"><input class="search" id="media-search" placeholder="Поиск изображения или документа" aria-label="Поиск медиа"><label class="btn primary">Загрузить файл +<input id="media-upload" type="file" accept="image/png,image/jpeg,image/webp,image/gif,image/svg+xml,application/pdf" hidden></label></div><p class="muted">JPG, PNG, WebP, GIF, SVG и PDF. До 20 МБ. Загрузка не меняет страницы автоматически.</p><div class="media-grid" id="media-grid"></div>`;
 if(picker)modal('Выберите файл',body);else $('#workspace-main').innerHTML=pageHead('Медиатека','Изображения, логотипы и документы вашего сайта.')+`<section class="panel">${body}</section>`;
 const grid=$('#media-grid');function draw(q=''){grid.innerHTML=S.media.filter(m=>(m.name+' '+m.path+' '+m.alt).toLowerCase().includes(q.toLowerCase())).map((m,i)=>`<article class="media-card">${m.image?`<button class="preview-select" data-path="${esc(m.path)}" aria-label="Выбрать ${esc(m.name)}"><img src="../${esc(m.path)}" alt="${esc(m.alt)}" loading="lazy"></button>`:'<div class="file-preview">PDF</div>'}<strong title="${esc(m.name)}">${esc(m.name)}</strong><small>${(m.bytes/1024).toFixed(1)} КБ</small><button class="btn small" data-path="${esc(m.path)}">${picker?'Выбрать':'Информация'}</button></article>`).join('')||'<p class="muted">Файлы не найдены.</p>';}
 draw();$('#media-search').oninput=e=>draw(e.target.value);grid.onclick=e=>{const b=e.target.closest('[data-path]');if(!b)return;const m=S.media.find(m=>m.path===b.dataset.path);if(picker){$('#modal').close();onPick(m);}else mediaDetails(m);};
 $('#media-upload').onchange=async e=>{const file=e.target.files[0];if(!file)return;const data=new FormData();data.set('file',file);data.set('revision',S.c.revision);try{await api('upload',data);toast('Файл загружен');await renderMedia(picker,onPick);}catch(error){toast(error.message,true);}};
}
function mediaDetails(m){modal('Файл в медиатеке',`<form id="media-form">${m.image?`<img src="../${esc(m.path)}" alt="" style="height:170px;max-width:100%;object-fit:contain;margin:0 auto 20px">`:''}${field('name','Название файла в панели',m.name)}${field('alt','Описание изображения (alt)',m.alt)}${field('path','Путь для вставки',m.path,'text','','readonly')}<p class="muted">Чтобы изменить подпись конкретной картинки на странице, выделите её в визуальном редакторе. Скрытие из библиотеки сохраняет уже размещённые изображения и резервные копии.</p></form>`,`${btn('Скрыть из библиотеки','media-hide',`data-path="${esc(m.path)}"`,'danger')}${btn('Сохранить','media-save',`data-path="${esc(m.path)}"`,'primary')}`);}
function editPage(file,slot=null,newPage=null){S.page=copy(newPage||S.c.pages[file]);S.slot=slot;S.view='page-editor';S.editorTab='visual';S.selected=null;S.undo=[];S.redo=[];S.dirty=false;if(slot)S.page.html=S.c.common[slot];renderPageEditor();}
function capturePage(){const iframe=$('#page-preview');if(!iframe?.contentDocument?.body)return S.page.html;const doc=iframe.contentDocument;const clone=doc.documentElement.cloneNode(true);$$('[data-editor-style],base',clone).forEach(n=>n.remove());$$('*',clone).forEach(n=>{[...n.attributes].forEach(a=>{if(a.name.startsWith('data-editor-')||a.name==='contenteditable')n.removeAttribute(a.name);});});if(S.slot){const node=$('.'+S.slot,clone);return node?.outerHTML||S.page.html;}return '<!doctype html>\n'+clone.outerHTML;}
function syncEditor(){if(S.editorTab==='visual')S.page.html=capturePage();else if(S.editorTab==='html')S.page.html=$('#page-code').value;else{const v=formValues($('#seo-form'));Object.assign(S.page,v);}}
function pushUndo(){const html=capturePage();if(S.undo.at(-1)!==html)S.undo.push(html);if(S.undo.length>35)S.undo.shift();S.redo=[];}
function renderPageEditor(){const slotNames={'topbar':'Верхняя полоса','header':'Шапка сайта','cta-band':'Блок обращения над подвалом','footer':'Подвал сайта'};const title=S.slot?slotNames[S.slot]:S.page.title;
 $('#workspace-main').innerHTML=pageHead(esc(title),S.slot?'Общий блок изменится на всех страницах после публикации.':'Выделите текст, изображение или раздел в макете. Товары, бренды и категории управляются в своих разделах.',`${btn('← Назад','editor-back')}${btn('Сохранить черновик','page-save','','primary')}`)+`<div class="tabs"><button class="${S.editorTab==='visual'?'active':''}" data-action="editor-tab" data-tab="visual">Визуальный редактор</button>${!S.slot?`<button class="${S.editorTab==='seo'?'active':''}" data-action="editor-tab" data-tab="seo">SEO и доступность</button>`:''}<button class="${S.editorTab==='html'?'active':''}" data-action="editor-tab" data-tab="html">HTML · расширенный режим</button></div><div id="editor-content"></div><p class="last-save" id="form-status">${S.dirty?'Есть несохранённые изменения':'Изменения сохраняются в черновик'}</p><p class="error" id="page-error"></p>`;
 if(S.editorTab==='visual'){
  $('#editor-content').innerHTML=`<div class="editor-shell"><div class="preview-wrap"><div class="preview-bar"><span>Предпросмотр · ссылки отключены</span><div class="actions">${btn('↶','editor-undo','','small')}${btn('↷','editor-redo','','small')}${btn('＋ Блок','editor-block','','small')}</div></div><iframe id="page-preview" title="Визуальный редактор страницы" sandbox="allow-same-origin"></iframe><div class="editor-help">Нажмите на элемент, чтобы изменить его в инспекторе справа. Шапка, подвал и верхняя полоса — в разделе «Общие блоки».</div></div><aside class="inspector" id="inspector"><h3>Инспектор элемента</h3><p class="muted">Выделите элемент на странице: заголовок, текст, кнопку или изображение.</p></aside></div>`;loadPreview();
 }else if(S.editorTab==='html'){
  $('#editor-content').innerHTML=`<p class="code-help">Расширенный режим для структуры и оформления. Обработчики JavaScript, внешние скрипты и iframe удаляются при сохранении. Перед публикацией проверьте макет в визуальном редакторе.</p><textarea class="code-editor" id="page-code" aria-label="HTML страницы" spellcheck="false">${esc(S.page.html)}</textarea>`;$('#page-code').oninput=changed;
 }else{
  $('#editor-content').innerHTML=`<form id="seo-form" class="panel form-block"><div class="grid-form">${field('file','Адрес страницы',S.page.file,'text','','readonly')}${field('title','Заголовок в поиске (title)',S.page.title,'text','','required maxlength="250"')}${area('description','Описание для поиска',S.page.description,'Кратко расскажите, что посетитель найдёт на странице.','full')}${imageField('image','Изображение для публикации в соцсетях',S.page.image)}</div>${check('noindex','Закрыть эту страницу от индексации',S.page.noindex)}${S.page.file!=='index.html'?check('archived','Убрать страницу в архив',S.page.archived,'После публикации на этом адресе будет показано сообщение о недоступности страницы.'):''}<p class="muted">Канонический адрес формируется из домена в настройках компании. Общий запрет индексации имеет приоритет над настройками страницы.</p></form>`;$('#seo-form').oninput=changed;
 }
}
function loadPreview(){const f=$('#page-preview');let html=S.page.html;if(S.slot){const d=new DOMParser().parseFromString(S.c.pages['index.html'].html,'text/html');d.body.innerHTML=html;html='<!doctype html>'+d.documentElement.outerHTML;}const d=new DOMParser().parseFromString(html,'text/html');$$('script',d).forEach(n=>n.remove());const base=d.createElement('base');base.href=new URL('../',location.href).href;d.head.prepend(base);const st=d.createElement('style');st.dataset.editorStyle='1';st.textContent='[data-editor-selected]{outline:2px solid #b49d00!important;outline-offset:4px!important}a,button,summary{cursor:crosshair!important}html{scroll-behavior:auto!important}body{min-width:0}';d.head.append(st);f.srcdoc='<!doctype html>'+d.documentElement.outerHTML;
 f.onload=()=>{const doc=f.contentDocument;doc.addEventListener('submit',e=>e.preventDefault(),true);doc.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();let n=e.target.closest('img,a,button,h1,h2,h3,h4,h5,p,span,small,strong,em,li,dt,dd,summary,label,section,div');if(!n||n===doc.body)return;if(!S.slot&&n.closest('header,footer,.topbar,.cta-band')){toast('Этот элемент относится к общим блокам сайта.');return;}selectElement(n);},true);};
}
function selectElement(node){S.selected?.removeAttribute('data-editor-selected');S.selected=node;node.dataset.editorSelected='1';const isImage=node.tagName==='IMG',isLink=node.tagName==='A',isBox=['SECTION','DIV'].includes(node.tagName);const box=$('#inspector');
 box.innerHTML=`<h3>${isImage?'Изображение':isLink?'Ссылка':isBox?'Раздел / контейнер':'Текстовый элемент'} <span class="muted">&lt;${node.tagName.toLowerCase()}&gt;</span></h3>${isImage?`${field('nodeImage','Изображение',node.getAttribute('src')||'')}<div class="actions" style="margin-bottom:12px">${btn('Медиатека','editor-image','','small')}</div>${field('nodeAlt','Описание (alt)',node.alt||'')}${select('nodeFit','Размещение',node.style.objectFit||'contain',[['contain','Целиком'],['cover','Заполнить область']])}`:!isBox?`${area('nodeText','Текст',node.innerText||node.textContent)}${isLink?field('nodeHref','Адрес ссылки',node.getAttribute('href')||''):''}<div class="format-tools">${btn('<strong>B</strong>','editor-format','data-format="strong"','small')}${btn('<em>I</em>','editor-format','data-format="em"','small')}${btn('Акцент','editor-format','data-format="accent"','small')}</div>${field('nodeSize','Размер текста, px',parseFloat(node.style.fontSize)||'','number','','min="8" max="160"')}${field('nodeColor','Цвет текста',node.style.color?rgbHex(node.style.color):'#171918','color')}`:'<p class="muted">Выделите текст или изображение внутри раздела для точного редактирования.</p>'}${select('nodeAlign','Выравнивание',node.style.textAlign||'left',[['left','Слева'],['center','По центру'],['right','Справа']])}<h3 style="margin-top:20px">Раздел страницы</h3><div class="actions">${btn('↑ Выше','editor-move','data-direction="-1"','small')}${btn('↓ Ниже','editor-move','data-direction="1"','small')}${btn('Дублировать','editor-duplicate','','small')}${btn(node.hidden?'Показать':'Скрыть','editor-hide','','small')}${btn('Удалить','editor-delete','','small danger')}</div><p class="muted" style="margin-top:14px">Отмена и повтор — кнопки ↶ ↷ над макетом. Удалённые опубликованные материалы можно вернуть из истории версий.</p>`;
 box.onfocusin=e=>{if(e.target.matches('input,textarea,select'))pushUndo();};box.oninput=e=>{const n=S.selected;if(!n)return;const key=e.target.name,value=e.target.value;try{
  if(key==='nodeImage')n.setAttribute('src',value);if(key==='nodeAlt')n.alt=value;if(key==='nodeFit')n.style.objectFit=value;if(key==='nodeHref')n.setAttribute('href',value);
  if(key==='nodeText'){const icons=$$('svg',n).map(s=>s.cloneNode(true));n.innerHTML=esc(value).replace(/\n/g,'<br>');icons.forEach(s=>n.append(s));}
  if(key==='nodeSize')n.style.fontSize=value?Math.min(160,Math.max(8,Number(value)))+'px':'';if(key==='nodeColor')n.style.color=value;if(key==='nodeAlign')n.style.textAlign=value;
  changed();
 }catch(error){toast('Не удалось изменить элемент.',true);}};
}
function rgbHex(rgb){const n=rgb.match(/\d+/g);return n?'#'+n.slice(0,3).map(v=>Number(v).toString(16).padStart(2,'0')).join(''):'#171918';}
function currentBlock(){return S.selected?.closest('section')||S.selected?.closest('main>div')||S.selected;}
function blockLibrary(){const templates=[['text','Текстовый раздел','Заголовок и свободный текст'],['image','Текст с изображением','Две колонки: описание и фотография'],['banner','Выделенный блок','Предложение и кнопка перехода'],['faq','Вопросы и ответы','Раскрывающиеся ответы'],['table','Таблица','Характеристики и условия']];modal('Добавить раздел',`<div class="three-col">${templates.map(([id,t,d])=>`<button class="panel" style="text-align:left;cursor:pointer" data-action="editor-add-block" data-template="${id}"><h2>${t}</h2><p class="muted">${d}</p><span>Добавить +</span></button>`).join('')}</div>`);}
function addBlock(type){const snippets={text:'<h2>Заголовок раздела</h2><p>Нажмите на этот текст, чтобы добавить информацию для посетителей сайта.</p>',image:'<div class="cms-columns"><div><h2>Заголовок раздела</h2><p>Расскажите о продукции, компании или условиях работы.</p></div><img src="assets/hero.jpg" alt="Описание изображения"></div>',banner:'<div class="cms-banner"><h2>Ваше предложение</h2><p>Краткое описание предложения для клиента.</p><a class="button" href="request.html">Оставить запрос →</a></div>',faq:'<h2>Вопросы и ответы</h2><div class="faq"><details open><summary>Вопрос клиента</summary><p>Подробный и понятный ответ.</p></details><details><summary>Ещё один вопрос</summary><p>Добавьте ответ для посетителя.</p></details></div>',table:'<h2>Условия и характеристики</h2><table class="cms-table"><thead><tr><th>Параметр</th><th>Значение</th></tr></thead><tbody><tr><td>Название параметра</td><td>Значение</td></tr><tr><td>Название параметра</td><td>Значение</td></tr></tbody></table>'};pushUndo();const doc=$('#page-preview').contentDocument;const section=doc.createElement('section');section.className='section cms-custom';section.innerHTML='<div class="wrap">'+snippets[type]+'</div>';const block=currentBlock();if(block?.parentElement && !S.slot)block.after(section);else(doc.querySelector('main')||doc.body).append(section);$('#modal').close();selectElement(section);section.scrollIntoView({block:'center'});changed();}
async function savePage(){try{syncEditor();const data={revision:S.c.revision};if(S.slot){data.slot=S.slot;data.html=S.page.html;await api('commonSave',data);}else{data.page=S.page;await api('pageSave',data);}saved();toast('Черновик сохранён. Сайт обновится после публикации.');}catch(error){$('#page-error').textContent=error.message;}}
function renderCommon(){const names={'topbar':['Верхняя полоса','Регион и информация о наличии'],'header':['Шапка сайта','Логотип, навигация и кнопки'],'cta-band':['Блок обращения','Призыв оставить запрос над подвалом'],'footer':['Подвал сайта','Описание, ссылки и данные компании']};$('#workspace-main').innerHTML=pageHead('Общие блоки','Редактирование этих элементов применяется ко всем страницам сайта после публикации.')+`<div class="two-col">${Object.entries(names).map(([key,[title,desc]])=>`<section class="panel"><h2>${title}</h2><p class="muted">${desc}</p>${btn('Редактировать блок →','common-edit',`data-slot="${key}"`)}</section>`).join('')}</div><p class="muted">Названия и порядок пунктов навигации меняются в «Меню сайта». Логотип, слоган и контакты — в настройках компании.</p>`;}
function renderNavigation(){const items=S.c.navigation;$('#workspace-main').innerHTML=pageHead('Меню сайта','Измените порядок, названия и адреса ссылок основного меню.')+`<form id="navigation-form" class="panel form-block"><div id="nav-rows">${items.map((v,i)=>navRow(v,i)).join('')}</div>${btn('Добавить пункт +','nav-add')}<div class="settings-sticky" style="margin-top:20px"><span id="form-status" class="last-save">Изменения сохраняются в черновик</span><button class="btn primary" type="submit">Сохранить меню</button></div></form>`;$('#navigation-form').oninput=changed;$('#navigation-form').onsubmit=async e=>{e.preventDefault();try{const rows=$$('.nav-row').map(r=>({title:$('[name=title]',r).value,url:$('[name=url]',r).value}));await api('navigationSave',{revision:S.c.revision,items:rows});saved();toast('Меню сохранено в черновик.');}catch(error){toast(error.message,true);}};}
function navRow(v,i){return `<div class="nav-row" style="display:grid;grid-template-columns:1fr 1fr auto;gap:12px;align-items:center;margin-bottom:12px"><div class="field" style="margin:0"><label>Название</label><input name="title" value="${esc(v.title)}" maxlength="60" aria-label="Название пункта ${i+1}"></div><div class="field" style="margin:0"><label>Адрес</label><input name="url" value="${esc(v.url)}" aria-label="Адрес пункта ${i+1}"></div><div class="actions" style="padding-top:20px">${btn('↑','nav-move','data-direction="-1"','small')}${btn('↓','nav-move','data-direction="1"','small')}${btn('×','nav-remove','','small danger')}</div></div>`;}
function renderSettings(){const v=S.c.settings;$('#workspace-main').innerHTML=pageHead('Компания и настройки','Контакты, оформление, поисковая индексация и подключение обращений.')+`<form id="settings-form" class="form-block"><section class="panel"><h2>Компания и контакты</h2><div class="grid-form">${field('companyName','Название компании',v.companyName,'text','','required')}${field('slogan','Слоган',v.slogan)}${field('phone','Телефон',v.phone,'tel')}${field('email','Контактный email',v.email,'email')}${field('warehouse','Адрес или описание склада',v.warehouse)}${field('hours','Режим работы',v.hours)}${field('address','Юридический адрес',v.address)}${field('legalName','Юридическое наименование',v.legalName)}${field('inn','ИНН',v.inn)}${field('ogrn','ОГРН',v.ogrn)}</div></section><section class="panel"><h2>Оформление</h2><div class="grid-form">${imageField('logo','Логотип',v.logo)}${imageField('favicon','Иконка сайта',v.favicon)}${field('accent','Акцентный цвет',v.accent,'color')}${field('ink','Основной тёмный цвет',v.ink,'color')}${field('paper','Светлая подложка',v.paper,'color')}${select('font','Шрифт',v.font,[['Manrope, Arial, sans-serif','Manrope'],['Arial, sans-serif','Arial'],['Georgia, serif','Georgia'],['system-ui, sans-serif','Системный шрифт']])}</div></section><section class="panel"><h2>Домен и поиск</h2>${field('siteUrl','Основной адрес сайта',v.siteUrl,'url','HTTPS-адрес без пути. Используется в canonical, sitemap и формах.','required')}${check('indexing','Разрешить индексацию сайта поисковыми системами',v.indexing,'Для отдельных страниц запрет можно установить в разделе SEO. Админ-панель всегда закрыта от индексации.')}</section><section class="panel"><h2>Обращения с сайта</h2>${check('inquiriesEnabled','Принимать обращения в админ-панель',v.inquiriesEnabled,'После включения обращения сохраняются в закрытом разделе «Обращения». Заполните контактный email и информацию об обработке данных на странице конфиденциальности.')}${check('mailNotifications','Отправлять почтовые уведомления о новых обращениях',v.mailNotifications)}${field('notificationEmail','Email для уведомлений',v.notificationEmail,'email','Уведомления отправляются средствами хостинга. Поступление писем нужно проверить после включения.')}<p class="muted">Пароли почты и SMTP-токены в публичных файлах сайта не используются.</p></section><p class="error" id="settings-error"></p><div class="settings-sticky"><span class="last-save" id="form-status">Изменения сохраняются в черновик</span><button class="btn primary" type="submit">Сохранить настройки</button></div></form>`;const f=$('#settings-form');f.oninput=changed;f.onsubmit=async e=>{e.preventDefault();try{await api('settingsSave',{revision:S.c.revision,settings:formValues(f)});saved();toast('Настройки сохранены в черновик.');}catch(error){$('#settings-error').textContent=error.message;}};}
async function renderHistory(){const r=await api('history');$('#workspace-main').innerHTML=pageHead('Версии и резервные копии','Хранится 40 последних версий содержимого. Восстановление создаёт черновик и не меняет действующий сайт до публикации.',`${btn('Скачать копию','backup-export')}${S.user.role==='owner'?btn('Загрузить копию','backup-import'):''}`)+`<section class="panel">${r.history.length?r.history.map(v=>`<div class="history-row"><div><strong>Версия ${v.revision} · ${prettyAction(v.label)}</strong><small>${date(v.at)}</small></div>${S.user.role==='owner'?btn('Восстановить','history-restore',`data-id="${v.id}"`,'small'):''}</div>`).join(''):'<p class="muted">История появится после первого сохранения. Перед каждым изменением создаётся снимок предыдущего состояния.</p>'}</section><p class="muted">Скачанная копия содержит страницы, каталог, настройки и ссылки на медиа. Пароли пользователей и обращения клиентов в неё не включаются. Оригиналы изображений сохраняйте отдельно.</p>`;}
async function renderInquiries(){if(S.user.role!=='owner'){$('#workspace-main').innerHTML=pageHead('Обращения','Этот раздел доступен администратору сайта.');return;}const r=await api('inquiries');S.inquiries=r.inquiries;$('#workspace-main').innerHTML=pageHead('Обращения','Запросы посетителей, полученные через формы сайта.')+(!S.c.settings.inquiriesEnabled?'<div class="warning">Приём обращений пока выключен. Его можно подключить в настройках компании после заполнения контактного email.</div>':'')+(r.inquiries.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Дата</th><th>Клиент</th><th>Тема</th><th>Статус</th><th></th></tr></thead><tbody>${r.inquiries.map(v=>`<tr><td>${date(v.at)}</td><td><strong>${esc(v.name)}</strong><small>${esc(v.email)}</small></td><td>${esc(v.topic)}</td><td><span class="pill ${v.status==='new'?'yellow':v.status==='done'?'green':''}">${{new:'Новое',working:'В работе',done:'Обработано',archived:'Архив'}[v.status]}</span></td><td>${btn('Открыть','inquiry-open',`data-id="${v.id}"`,'small')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><h2>Новых обращений пока нет</h2><p>После подключения форм здесь появятся запросы клиентов.</p></div>');}
function showInquiry(id){const v=S.inquiries.find(v=>v.id===id);modal(esc(v.topic),`<ul class="info-list"><li><span>Номер / дата</span><strong>${esc(v.id)} · ${date(v.at)}</strong></li><li><span>Имя</span><strong>${esc(v.name)}</strong></li><li><span>Email</span><a href="mailto:${esc(v.email)}">${esc(v.email)}</a></li><li><span>Телефон</span><strong>${esc(v.phone||'Не указан')}</strong></li></ul><div class="inquiry-message">${esc(v.message)}</div><p class="muted">Согласие на использование контактов получено при отправке формы.</p>${select('inquiryStatus','Статус',v.status,[['new','Новое'],['working','В работе'],['done','Обработано'],['archived','Архив']])}`,btn('Сохранить статус','inquiry-status',`data-id="${v.id}"`,'primary'));}
async function renderUsers(){const r=await api('users');S.users=r.users;$('#workspace-main').innerHTML=pageHead('Пользователи','Администратор управляет доступом и всеми настройками. Редактор меняет содержание и публикует сайт.',btn('Добавить пользователя +','user-edit','','primary'))+`<div class="table-wrap"><table class="data-table"><thead><tr><th>Пользователь</th><th>Email</th><th>Роль</th><th>Статус</th><th></th></tr></thead><tbody>${r.users.map(v=>`<tr><td><strong>${esc(v.name)}</strong></td><td>${esc(v.email)}</td><td>${v.role==='owner'?'Администратор':'Редактор'}</td><td>${v.active?'Активен':'Отключён'}</td><td>${btn('Изменить','user-edit',`data-id="${v.id}"`,'small')}</td></tr>`).join('')}</tbody></table></div>`;}
function userEditor(id){const v=S.users?.find(v=>v.id===id)||{id:'',name:'',email:'',role:'editor',active:true};modal(v.id?'Настройки пользователя':'Новый пользователь',`<form id="user-form">${field('name','Имя',v.name,'text','','required')}${field('email','Email для входа',v.email,'email','','required')}${select('role','Роль',v.role,[['editor','Редактор'],['owner','Администратор']])}${field('password',v.id?'Новый пароль · необязательно':'Пароль','','password','От 12 символов.',`autocomplete="new-password" minlength="12" maxlength="200" ${v.id?'':'required'}`)}${check('active','Активная учётная запись',v.active)}<p class="error" id="user-error"></p></form>`,btn('Сохранить пользователя','user-save',`data-id="${v.id}"`,'primary'));}
async function renderAudit(){const r=await api('audit');$('#workspace-main').innerHTML=pageHead('Журнал действий','Входы, изменения материалов, публикации и восстановление версий.')+`<div class="table-wrap"><table class="data-table"><thead><tr><th>Дата</th><th>Действие</th><th>Пользователь</th><th>Версия / объект</th></tr></thead><tbody>${r.audit.slice(0,300).map(v=>`<tr><td>${date(v.at)}</td><td>${esc(prettyAction(v.action))}</td><td>${esc(v.user==='guest'?'Посетитель':v.user===S.user.id?'Вы':v.user)}</td><td>${esc(v.meta.revision?'№ '+v.meta.revision:v.meta.id||'—')}</td></tr>`).join('')}</tbody></table></div>`;}
function renderAccount(){$('#workspace-main').innerHTML=pageHead('Моя учётная запись',S.user.email)+`<form id="password-form" class="panel form-block" style="max-width:600px"><h2>Изменить пароль</h2>${field('currentPassword','Текущий пароль','','password','','autocomplete="current-password" required')}${field('password','Новый пароль','','password','Не менее 12 символов.','autocomplete="new-password" minlength="12" maxlength="200" required')}${field('passwordRepeat','Повторите новый пароль','','password','','autocomplete="new-password" minlength="12" maxlength="200" required')}<p class="error" id="password-error"></p><button class="btn primary" type="submit">Изменить пароль</button></form>`;const f=$('#password-form');f.onsubmit=async e=>{e.preventDefault();try{await api('password',formValues(f));f.reset();toast('Пароль изменён. Другие сеансы завершены.');}catch(error){$('#password-error').textContent=error.message;}};}
async function renderView(){const main=$('#workspace-main');try{if(S.view==='dashboard')renderDashboard();else if(S.view==='pages')renderPages();else if(['products','categories','brands','offers'].includes(S.view))renderEntities(S.view);else if(S.view==='media')await renderMedia();else if(S.view==='common')renderCommon();else if(S.view==='navigation')renderNavigation();else if(S.view==='settings')renderSettings();else if(S.view==='history')await renderHistory();else if(S.view==='inquiries')await renderInquiries();else if(S.view==='users')await renderUsers();else if(S.view==='audit')await renderAudit();else if(S.view==='account')renderAccount();else renderDashboard();}catch(error){main.innerHTML=pageHead('Не удалось загрузить раздел',esc(error.message),btn('Повторить','reload'));}}
async function downloadExport(action){const r=await fetch('api.php?action='+action,{credentials:'same-origin'});if(!r.ok)throw Error('Не удалось скачать файл. Войдите в панель повторно.');const blob=await r.blob();const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=action==='exportProducts'?'specparts49-products.csv':'specparts49-content-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function importProducts(){S.csv='';S.importPlan=null;modal('Импорт каталога из CSV',`<p class="muted">Обязательные столбцы: <strong>article;name</strong>. Дополнительно: brand;cat;price;quantity;stock;image;desc;published. Разделитель — «;» или запятая. Кодировка UTF-8 или Windows-1251. Существующий товар определяется по id, а без него — по артикулу и бренду.</p><label class="btn">Выбрать CSV-файл<input id="csv-file" type="file" accept=".csv,text/csv" hidden></label><div style="margin-top:18px">${area('csv','Или вставьте содержимое CSV','','До 5000 строк за один импорт.')}</div><div id="csv-result"></div>`,`${btn('Проверить файл','csv-check','','primary')}${btn('Импортировать в черновик','csv-apply','disabled','dark')}`);$('#csv-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>5*1024*1024){toast('Файл больше 5 МБ.',true);return;}const bytes=await f.arrayBuffer();let text=new TextDecoder('utf-8',{fatal:false}).decode(bytes);if(text.includes('\uFFFD'))text=new TextDecoder('windows-1251').decode(bytes);$('#f-csv').value=text;};}
async function publishSite(){if(S.dirty){toast('Сначала сохраните открытую форму в черновик.',true);return;}const count=Object.values(S.c.pages).filter(p=>!p.archived).length;if(!await confirmBox('Опубликовать изменения?',`Будет опубликована версия <strong>№ ${S.c.revision}</strong>: ${count} страниц, каталог, бренды, акции и общие настройки. Посетители увидят обновлённый сайт.`,'Опубликовать'))return;try{const r=await api('publish',{revision:S.c.revision});toast('Сайт опубликован · версия '+r.publication.revision);S.dirty=false;await load();}catch(error){toast(error.message,true);}}
async function handleAction(action,b){
 if(action==='close-modal'){$('#modal').close();return;}
 if(action==='toggle-nav'){$('#sidebar').classList.toggle('open');return;}
 if(action==='publish'){await publishSite();return;}
 if(action==='logout'){if(S.dirty&&!await confirmBox('Выйти из панели?','Несохранённые изменения открытой формы будут потеряны.','Выйти'))return;await api('logout',{});S.user=null;S.dirty=false;renderAuth(true);return;}
 if(action==='nav-pages'){await go('pages');return;}if(action==='reload'){await load();return;}
 if(action==='entity-new'||action==='entity-edit'){if(S.dirty)return;editEntity(b.dataset.collection,b.dataset.id);return;}
 if(action==='back-entities'){await go(b.dataset.collection);return;}
 if(action==='entity-archive-view'){S.archived=!S.archived;renderEntities(b.dataset.collection);return;}
 if(action==='entity-archive'){const key=b.dataset.collection,v=S.c[key].find(v=>v.id===b.dataset.id);if(!await confirmBox(v.archived?'Восстановить запись?':'Переместить в архив?',`<strong>${esc(v.name)}</strong>${v.archived?' вернётся в черновик.':' будет скрыта после публикации. Восстановить запись можно в архиве раздела.'}`,v.archived?'Восстановить':'В архив'))return;await api('entityArchive',{revision:S.c.revision,collection:key,id:v.id,archived:!v.archived});renderEntities(key);updateTop();toast('Черновик обновлён.');return;}
 if(action==='pick-field'){await renderMedia(true,m=>{const n=document.querySelector(`[name="${b.dataset.field}"]`);n.value=m.path;n.dispatchEvent(new Event('input',{bubbles:true}));});return;}
 if(action==='media-save'||action==='media-hide'){const f=$('#media-form');if(action==='media-hide'&&!await confirmBox('Скрыть файл из медиатеки?','Файл продолжит работать на уже размещённых страницах. Его оригинал и история сохранятся.','Скрыть'))return;await api('mediaSave',{revision:S.c.revision,...formValues(f),archived:action==='media-hide'});$('#modal').close();await renderMedia();updateTop();toast('Медиатека обновлена.');return;}
 if(action==='page-edit'){editPage(b.dataset.id);return;}
 if(action==='page-new'){modal('Новая страница',`<form id="new-page-form">${field('title','Название страницы','','text','','required')}${field('file','Адрес страницы','','text','Латиница и дефис, с окончанием .html. Например: services.html.','pattern="[a-z0-9][a-z0-9-]{0,70}\\.html" required')}<p class="error" id="new-page-error"></p></form>`,btn('Создать черновик','page-create','','primary'));return;}
 if(action==='page-create'){const f=$('#new-page-form');if(!f.reportValidity())return;const v=formValues(f);if(S.c.pages[v.file]){$('#new-page-error').textContent='Этот адрес уже используется.';return;}const d=new DOMParser().parseFromString(S.c.pages['about.html'].html,'text/html');const main=d.querySelector('main');main.innerHTML='<section class="section"><div class="wrap"><h1>'+esc(v.title)+'</h1><p>Добавьте содержание страницы в визуальном редакторе.</p></div></section>';$('#modal').close();editPage(v.file,null,{file:v.file,title:v.title+' — '+S.c.settings.companyName,description:'',image:'assets/hero.jpg',noindex:false,archived:false,html:'<!doctype html>'+d.documentElement.outerHTML});changed();return;}
 if(action==='common-edit'){editPage('index.html',b.dataset.slot);return;}
 if(action==='editor-back'){await go(S.slot?'common':'pages');return;}
 if(action==='editor-tab'){syncEditor();S.editorTab=b.dataset.tab;renderPageEditor();return;}
 if(action==='page-save'){await savePage();return;}
 if(action==='editor-block'){blockLibrary();return;}if(action==='editor-add-block'){addBlock(b.dataset.template);return;}
 if(action==='editor-undo'||action==='editor-redo'){const source=action==='editor-undo'?S.undo:S.redo,target=action==='editor-undo'?S.redo:S.undo;if(!source.length)return;target.push(capturePage());S.page.html=source.pop();S.selected=null;loadPreview();$('#inspector').innerHTML='<p class="muted">Выделите элемент на странице.</p>';changed();return;}
 if(action==='editor-image'){await renderMedia(true,m=>{pushUndo();S.selected.src=m.path;if(m.alt)S.selected.alt=m.alt;changed();selectElement(S.selected);});return;}
 if(action==='editor-format'){if(!S.selected)return;pushUndo();if(b.dataset.format==='accent')S.selected.style.color=S.c.settings.accent;else S.selected.innerHTML='<'+b.dataset.format+'>'+S.selected.innerHTML+'</'+b.dataset.format+'>';changed();return;}
 if(['editor-move','editor-duplicate','editor-hide','editor-delete'].includes(action)){const block=currentBlock();if(!block)return;if(action==='editor-delete'&&!await confirmBox('Удалить раздел?','Раздел будет удалён из текущего макета. Действие можно отменить кнопкой ↶ до выхода из редактора.','Удалить',true))return;pushUndo();if(action==='editor-move'){const sibling=Number(b.dataset.direction)<0?block.previousElementSibling:block.nextElementSibling;if(sibling){if(Number(b.dataset.direction)<0)sibling.before(block);else sibling.after(block);}}if(action==='editor-duplicate'){const clone=block.cloneNode(true);$$('[id]',clone).forEach(n=>n.removeAttribute('id'));clone.removeAttribute('id');block.after(clone);selectElement(clone);}if(action==='editor-hide'){block.hidden=!block.hidden;selectElement(S.selected);}if(action==='editor-delete'){block.remove();S.selected=null;$('#inspector').innerHTML='<p class="muted">Раздел удалён. Можно отменить кнопкой ↶.</p>';}changed();return;}
 if(action==='nav-add'){$('#nav-rows').insertAdjacentHTML('beforeend',navRow({title:'',url:''},$$('.nav-row').length));changed();return;}
 if(action==='nav-remove'){b.closest('.nav-row').remove();changed();return;}
 if(action==='nav-move'){const row=b.closest('.nav-row'),s=Number(b.dataset.direction)<0?row.previousElementSibling:row.nextElementSibling;if(s){Number(b.dataset.direction)<0?s.before(row):s.after(row);changed();}return;}
 if(action==='history-restore'){if(!await confirmBox('Восстановить версию?','Содержание выбранной версии заменит текущий черновик. Действующий сайт обновится только после публикации.','Восстановить'))return;await api('restore',{revision:S.c.revision,id:b.dataset.id});toast('Версия восстановлена в черновик.');await renderHistory();updateTop();return;}
 if(action==='backup-export'){await downloadExport('export');return;}if(action==='export-products'){await downloadExport('exportProducts');return;}
 if(action==='backup-import'){modal('Восстановить из файла',`<p class="muted">Выберите JSON-копию, скачанную из этой панели. Аккаунты пользователей и обращения не изменятся. Результат сначала сохранится как черновик.</p><input id="backup-file" type="file" accept=".json,application/json"><p id="backup-error" class="error"></p>`,btn('Загрузить в черновик','backup-apply','','primary'));return;}
 if(action==='backup-apply'){const f=$('#backup-file').files[0];if(!f){$('#backup-error').textContent='Выберите файл.';return;}if(f.size>15*1024*1024)throw Error('Копия должна быть меньше 15 МБ.');try{const backup=JSON.parse(await f.text());await api('restoreFile',{revision:S.c.revision,backup});$('#modal').close();await renderHistory();updateTop();toast('Копия загружена в черновик.');}catch(error){$('#backup-error').textContent=error.message;}return;}
 if(action==='import-products'){importProducts();return;}
 if(action==='csv-check'){const csv=$('#f-csv').value;const r=await api('importProducts',{revision:S.c.revision,csv,dryRun:true});S.csv=csv;S.importPlan=r.plan;$('#csv-result').innerHTML=`<div class="${r.plan.errors.length?'warning':'success'}">Новых товаров: ${r.plan.create}. Обновлений: ${r.plan.update}.${r.plan.errors.length?'<br>'+r.plan.errors.slice(0,20).map(esc).join('<br>'):''}</div><pre class="csv-preview">${esc(r.plan.rows.slice(0,8).map(r=>r.row+'. '+r.item.article+' · '+r.item.name).join('\n'))}</pre>`;$('[data-action=csv-apply]').disabled=!!r.plan.errors.length||!r.plan.rows.length;return;}
 if(action==='csv-apply'){if($('#f-csv').value!==S.csv)throw Error('Файл изменён после проверки. Нажмите «Проверить файл».');await api('importProducts',{revision:S.c.revision,csv:S.csv,dryRun:false});$('#modal').close();toast('Каталог импортирован в черновик.');await go('products');return;}
 if(action==='inquiry-open'){showInquiry(b.dataset.id);return;}
 if(action==='inquiry-status'){await api('inquiryStatus',{id:b.dataset.id,status:$('#f-inquiryStatus').value});$('#modal').close();await renderInquiries();toast('Статус сохранён.');return;}
 if(action==='user-edit'){userEditor(b.dataset.id);return;}
 if(action==='user-save'){const f=$('#user-form');if(!f.reportValidity())return;try{await api('userSave',{user:{id:b.dataset.id,...formValues(f)}});$('#modal').close();await renderUsers();toast('Пользователь сохранён.');}catch(error){$('#user-error').textContent=error.message;}return;}
}
document.addEventListener('click',async e=>{const nav=e.target.closest('[data-nav]');if(nav){e.preventDefault();try{await go(nav.dataset.nav);}catch(error){toast(error.message,true);}return;}const b=e.target.closest('[data-action]');if(!b||b.dataset.action==='modal-confirm')return;e.preventDefault();try{await handleAction(b.dataset.action,b);}catch(error){toast(error.message,true);}});
let searchTimer;document.addEventListener('input',e=>{if(e.target.dataset.search){const field=e.target,view=e.target.dataset.search;S.query=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const pos=field.selectionStart;if(view==='pages')renderPages();else renderEntities(view);const next=$('[data-search]');next.focus();next.setSelectionRange(pos,pos);},130);}});
window.addEventListener('beforeunload',e=>{if(S.dirty){e.preventDefault();e.returnValue='';}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close();});
(async()=>{try{if(S.setupKey)history.replaceState(null,'',location.pathname);const status=await api('status');S.csrf=status.csrf;S.user=status.user;if(S.user)await load();else renderAuth(status.installed,status.setupReady);}catch(error){$('#app').innerHTML=`<div class="boot"><h1>Панель временно недоступна</h1><p class="error">${esc(error.message)}</p><a class="btn" href="./">Повторить</a></div>`;}})();
